public class DOMNodePointer_getValue_TriageGen1Test {

    private Document createTestDocument() throws Exception {
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        factory.setNamespaceAware(true);
        DocumentBuilder builder = factory.newDocumentBuilder();
        Document doc = builder.newDocument();
        Element root = doc.createElement("root");
        doc.appendChild(root);
        return doc;
    }

    @Test
    public void testGetValue_WithTextNode() throws Exception {
        Document doc = createTestDocument();
        Element root = doc.getDocumentElement();
        Text textNode = doc.createTextNode("Hello JXPath");
        root.appendChild(textNode);

        DOMNodePointer pointer = new DOMNodePointer(textNode, Locale.ENGLISH);
        Object value = pointer.getValue();

        assertEquals("Hello JXPath", value);
    }










}

